'use server';

import { createAdminClient } from '@/lib/supabase/admin';
import { logAdminAction } from '@/lib/audit';
import { revalidatePath } from 'next/cache';

/**
 * Bans a user by updating their profile status and logging the action.
 * @param adminId - The ID of the admin performing the action.
 * @param userId - The ID of the user to ban.
 * @param reason - The reason for banning the user.
 */
export async function banUser(adminId: string, userId: string, reason: string) {
  const supabase = await createAdminClient();

  // 1. Update the user's profile status
  const { error } = await supabase
    .from('profiles')
    .update({ 
      status: 'banned',
      metadata: { ban_reason: reason, banned_by: adminId, banned_at: new Date().toISOString() } 
    } as any) // Casting as any because types might not be regenerated yet
    .eq('id', userId);

  if (error) {
    console.error('Error banning user:', error);
    throw new Error(`Failed to ban user: ${error.message}`);
  }

  // 2. Log the action
  try {
    await logAdminAction(adminId, 'user_banned', userId, 'user', { reason });
  } catch (logError) {
    // In a strict system, we might want to rollback the ban here.
    console.error('Audit log failed for banUser:', logError);
  }

  // 3. Revalidate paths to refresh UI
  revalidatePath('/dashboard/users');
  revalidatePath(`/dashboard/users/${userId}`);
  
  return { success: true };
}

/**
 * Unbans a user.
 */
export async function unbanUser(adminId: string, userId: string) {
  const supabase = await createAdminClient();

  const { error } = await supabase
    .from('profiles')
    .update({ 
      status: 'active',
      metadata: { unbanned_by: adminId, unbanned_at: new Date().toISOString() } 
    } as any)
    .eq('id', userId);

  if (error) {
    throw new Error(`Failed to unban user: ${error.message}`);
  }

  await logAdminAction(adminId, 'user_unbanned', userId, 'user');

  revalidatePath('/dashboard/users');
  revalidatePath(`/dashboard/users/${userId}`);

  return { success: true };
}

/**
 * Manually verifies a user.
 */
export async function verifyUser(adminId: string, userId: string) {
  const supabase = await createAdminClient();

  // Assuming we might use a metadata flag for verification if not a column
  // Or if we decide to add is_verified column later. For now, let's just log it and maybe add a metadata tag.
  const { error } = await supabase
    .from('profiles')
    .update({ 
      metadata: { is_verified: true, verified_by: adminId, verified_at: new Date().toISOString() } 
    } as any)
    .eq('id', userId);

  if (error) {
    throw new Error(`Failed to verify user: ${error.message}`);
  }

  await logAdminAction(adminId, 'user_verified', userId, 'user');

  revalidatePath('/dashboard/users');
  revalidatePath(`/dashboard/users/${userId}`);

  return { success: true };
}
