'use server';

import { createAdminClient } from '@/lib/supabase/admin';
import { logAdminAction } from '@/lib/audit';
import { revalidatePath } from 'next/cache';

/**
 * Resolves a dispute by calling the secure RPC function.
 * @param adminId - ID of the admin.
 * @param disputeId - ID of the dispute to resolve.
 * @param decision - 'refund_client' or 'release_freelancer'.
 */
export async function resolveDispute(
  adminId: string, 
  disputeId: string, 
  decision: 'refund_client' | 'release_freelancer'
) {
  const supabase = await createAdminClient();

  // 1. Call the RPC
  const { error } = await supabase.rpc('admin_resolve_dispute', {
    p_dispute_id: disputeId,
    p_decision: decision
  });

  if (error) {
    console.error('Error resolving dispute:', error);
    throw new Error(`Failed to resolve dispute: ${error.message}`);
  }

  // 2. Log the action
  try {
    await logAdminAction(adminId, 'dispute_resolved', disputeId, 'dispute', { decision });
  } catch (logError) {
    console.error('Audit log failed for resolveDispute:', logError);
  }

  // 3. Revalidate paths
  revalidatePath('/dashboard/disputes');
  revalidatePath('/dashboard/finance'); // Balances changed
  revalidatePath(`/dashboard/disputes/${disputeId}`);

  return { success: true };
}
